-- People (public team)
INSERT OR IGNORE INTO "Person" ("id", "name", "slug", "bio", "photoUrl", "birthYear", "nationality", "website", "imdbUrl", "notes", "createdAt", "updatedAt") VALUES ('person_owas-ray-mwape', 'Owas Ray Mwape', 'owas-ray-mwape', 'Zambian actor, director and producer. National Best Actor awards in 1990, 1991 and 1992. Founded Owas Films in 2013; leads Oram Media Dynamics. Public credits include directing Zuba for Zambezi Magic, creative leadership on Inkondo, and features Graft and Look in the Mirror.', '/media/team/owas-ray-mwape-ep.jpg', NULL, 'Zambian', NULL, NULL, 'Public role: CEO & Film Director', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT OR IGNORE INTO "Person" ("id", "name", "slug", "bio", "photoUrl", "birthYear", "nationality", "website", "imdbUrl", "notes", "createdAt", "updatedAt") VALUES ('person_adorah-mwape', 'Adorah Mwape', 'adorah-mwape', 'Actress, scriptwriter, producer, and director behind Owas Crystal Films. Producer of Strictly By Invitation; credits associated with Secrets Untold and related Owas Films titles.', '/about/adorah-mwape.png', NULL, 'Zambian', NULL, NULL, 'Public role: Executive Producer', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');
INSERT OR IGNORE INTO "Person" ("id", "name", "slug", "bio", "photoUrl", "birthYear", "nationality", "website", "imdbUrl", "notes", "createdAt", "updatedAt") VALUES ('person_production-team', 'Production Team', 'production-team', 'Camera, lighting and production teams delivering Oram TV and Oram Entertainment work across Lusaka sets and locations.', '/media/bts/inkondo-shoot-s2-b.jpg', NULL, 'Zambian', NULL, NULL, 'Public role: Oram Media Dynamics Crew', '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z');

