      "createdAt", "updatedAt"
    ) VALUES (
      'prod_inkondo', 'Inkondo', 'inkondo', '[]',
      2025, NULL, 'Drama series', 'tv-series',
      'released', 'published', 'directed-by-owas', 'A Zambezi Magic original: rival families, bus-war territory, and a love that crosses the line — premiered 5 May 2025.', 'Inkondo is a dramatic tale of forbidden love between the children of two rival families torn apart by years of betrayal, violence, and secrets. MultiChoice Studios frames the series as a rivalry that began generations ago — until fate joins Chiyumba’s daughter Nampindi and Mazoka’s son Dimuna. The series premiered 5 May 2025 at 20:00 CAT on Zambezi Magic (DStv Channel 162 / GOtv Channel 3 Supa), airing Mondays, Tuesdays and Wednesdays, with MultiChoice’s Power of Three platforms (DStv, GOtv, Showmax) carrying the local slate.',
      'Replace the vacated Zuba slot with a new Zambezi Magic original that could hold a three-night weekly appointment — large ensemble, local politics of power, romance under pressure — for linear broadcast and Showmax.', 'An all-local creative leadership pairing of Jackson (Jay Rox) Banda and film director Owas Ray Mwape. Premiere materials describe the series as mirroring “the real tensions, passions, and hopes of our communities,” with a cast mixing established and rising Zambian performers.', 'Shot and finished for MultiChoice’s Zambezi Magic pipeline. Oram TV documented production for audiences through on-set InLens-Inkondo coverage across Lusaka locations, including outdoor quarry/set work and interior multi-camera days preserved in the ORAM stills archive.',
      'ORAM’s archive holds Season 2 set photography: camera and boom teams on red earth locations, lighting crew at work indoors, and cast/process frames from the shoot. Public premiere cast named in announcement materials includes Luke Mumba, Rosheni Mwemba, Evans Phiri, Sophia Chapeshamano and Zen Vlahakis.', NULL, '[{"value":"5 May 2025","label":"Premiere · 20:00 CAT"},{"value":"DStv 162","label":"Zambezi Magic · GOtv 3 Supa"},{"value":"Showmax","label":"Streaming home"},{"value":"Mon–Wed","label":"Weekly slot"}]', '["Premiere slot: Mondays–Wednesdays at 20:00 CAT on Zambezi Magic.","Announced in MultiChoice Zambia’s 2025 local content showcase alongside Pa Maliketi Season 2.","Oram TV documented production as InLens-Inkondo set coverage."]',
      'Creative leadership — Jackson (Jay Rox) Banda and director Owas Ray Mwape (public materials). Classified as Directed by Owas Ray Mwape.', NULL, NULL, 'MultiChoice / Zambezi Magic original', NULL,
      'Zambezi Magic / MultiChoice', 'Zambezi Magic (DStv 162 · GOtv 3 Supa)', 'Showmax',
      1, 1, 0, 1,
      'Inkondo', 'A Zambezi Magic original: rival families, bus-war territory, and a love that crosses the line — premiered 5 May 2025.', NULL, NULL, 1,
      'overview', NULL, NULL, NULL, NULL, '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z'
    );
