    ) VALUES (
      'prod_graft', 'Graft', 'graft', '[]',
      2024, NULL, 'Feature', 'feature',
      'released', 'published', 'oram-co-production', '2024 Zambian feature — “When Corruption Sinks Everyone.” Directed and produced by Owas Ray Mwape.', 'Graft (2024) is a Zambian drama feature directed and produced by Owas Ray Mwape. The theatrical key art is presented by Oram Media Works and Owas Films Production in association with Oram Film Training Academy. The poster tagline — “When Corruption Sinks Everyone” — frames a story that sets a family unit against archetypes of power: business, medicine, and academia. IMDbPro lists Kangwa Chileshe and Sophie Mbao among the cast.',
      'Mount an independent Zambian feature under the Owas Films / Oram banner — a corruption drama with theatrical key art and a cast drawn from Zambian screen talent — without the marketing machine of a network original.', 'Owas Ray Mwape directed and produced. Key art centres on a portrait theatrical poster with full billing. Oram TV published life-on-set documentation during the shoot, including work with Alfred Njovu on camera.', 'Independent feature workflow under Oram Media Works / Owas Films, with Oram Film Training Academy associated on the public billing. Unit photography beyond the poster collage remains thin in the public web archive — the HD poster is the primary official image asset.',
      'Oram TV’s Facebook set documentation records the Lusaka shoot. Cleared production stills for the public site are still outstanding; until then the gallery leads with the official theatrical poster only.', NULL, '[{"value":"2024","label":"Feature year (IMDbPro)"},{"value":"Owas Ray Mwape","label":"Director · Producer"},{"value":"Theatrical","label":"Portrait key art"}]', '[]',
      'Oram Media Works · Oram Film Training Academy billed with Owas Films on official poster — ORAM Media Dynamics Co-Production.', NULL, NULL, 'Oram Media Works · Owas Films · Oram Film Training Academy', NULL,
      'Owas Films / Oram Media Dynamics', NULL, NULL,
      1, 3, 1, 1,
      'Graft', '2024 Zambian feature — “When Corruption Sinks Everyone.” Directed and produced by Owas Ray Mwape.', NULL, NULL, 0,
      'overview', NULL, NULL, NULL, NULL, '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z'
    );
