    ) VALUES (
      'prod_secrets-untold', 'Secrets Untold', 'secrets-untold', '[]',
      2015, NULL, 'Feature', 'feature',
      'released', 'published', 'oram-co-production', '2015 feature — written and directed by Owas Ray Mwape. Ster Kinekor, Lusaka premiere.', 'Secrets Untold (also billed as Secrets Untold: The Wife 2) is a 2015 Zambian drama written and directed by Owas Ray Mwape, with screenplay credit to Ivory van der Boom in contemporary press. Lusaka Times reported a Ster Kinekor red-carpet premiere in Lusaka (coverage dated 17 November 2015; listings also place a 30 October 2015 premiere). The film examines secrets inside marriage — what breaks a couple and what holds them. Cast named in press includes Owas Ray Mwape, Cassie Kabwita, Catherine Soko, Wanga Zulu, James Banda, Adorah Mwape, Chilala Mainza, Gift Muneka, Max Owas and Titus Sinyangwe. Poster billing lists Owas Crystal Films, Old Age Productions and X-Konvict Pictures, with ORAM as Executive Producer.',
      'Premiere an independent Zambian feature in a commercial cinema when local theatrical pathways were still narrow — and treat marriage drama as subject matter worth a red carpet.', 'Owas Ray Mwape wrote and directed after founding Owas Films in 2013. The Ster Kinekor Lusaka premiere positioned the film for a paying public audience, not only a private industry screening.', 'Independent feature under Owas Crystal Films / associated labels. No official YouTube trailer is wired; do not substitute the studio showreel as the film trailer.',
      'Press coverage of the premiere survives in Lusaka Times. Cleared BTS stills are not yet in the public web gallery.', NULL, '[{"value":"2015","label":"Release year"},{"value":"Ster Kinekor","label":"Lusaka premiere"},{"value":"ORAM","label":"Executive Producer (poster)"}]', '[]',
      'Executive Producer (poster billing: ORAM) — ORAM Media Dynamics Co-Production.', NULL, NULL, 'Owas Crystal Films · Old Age Productions · X-Konvict Pictures', NULL,
      'Owas Films / Owas Crystal Films', NULL, NULL,
      1, 8, 1, 1,
      'Secrets Untold', '2015 feature — written and directed by Owas Ray Mwape. Ster Kinekor, Lusaka premiere.', NULL, NULL, 0,
      'overview', NULL, NULL, NULL, NULL, '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z'
    );
