    ) VALUES (
      'prod_hang', 'Hang!', 'hang', '["hang! A Cry of an Artist"]',
      2018, NULL, 'Feature', 'feature',
      'released', 'published', 'oram-co-production', '2018 comedy-drama — “A Cry of an Artist.” Directed by Owas Ray Mwape; ORAM as Executive Producer.', 'Hang! (2018) is a Zambian comedy-drama directed by Owas Ray Mwape. IMDbPro summarises the plot: an unemployed artist creates a storm of media attention when he threatens to hang himself on an area of disputed land. The official poster bills the film as “hang! A CRY OF AN ARTIST,” presented by Owas Crystal Films and Old Age Productions as an Owas Ray Mwape film, with Owas Films / Owas Crystal Films / Old Age Productions on the production line and ORAM.EXP.MARKETING LTD as Executive Producer. Zambia release is listed as 10 February 2018 (IMDbPro).',
      'Tell a darkly comic story about an artist, disputed land and media spectacle — and put it on a theatrical poster with a clear ORAM executive-producer credit.', 'Owas Ray Mwape directed and co-wrote with Adorah Mwape. Adorah produced. Key art centres on a single confrontational portrait rather than a cast collage.', 'Independent feature under Owas Crystal Films / Old Age Productions / Owas Films. No official YouTube trailer is wired on this site yet.',
      'Alternate poster frames exist in the ORAM vault (Hang 2). Cleared unit stills are not yet in the public gallery.', NULL, '[{"value":"10 Feb 2018","label":"Zambia release (IMDbPro)"},{"value":"ORAM","label":"Executive Producer (poster)"},{"value":"Feature","label":"Comedy-drama"}]', '["IMDbPro Zambia release date: 10 February 2018.","Poster presents the film as “An Owas Ray Mwape Film.”","DoP on poster: Macrony Kasitu."]',
      'Executive Producer — ORAM.EXP.MARKETING LTD (official poster) — ORAM Media Dynamics Co-Production.', NULL, NULL, 'Owas Films · Owas Crystal Films · Old Age Productions', NULL,
      'Owas Films / ORAM', NULL, NULL,
      1, 6, 1, 1,
      'Hang!', '2018 comedy-drama — “A Cry of an Artist.” Directed by Owas Ray Mwape; ORAM as Executive Producer.', NULL, NULL, 0,
      'overview', NULL, NULL, NULL, NULL, '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z'
    );
