    ) VALUES (
      'prod_pa-maliketi', 'Pa Maliketi', 'pa-maliketi', '[]',
      2023, NULL, 'TV series', 'tv-series',
      'released', 'published', 'directed-by-owas', 'Zambezi Magic market comedy — when Mwansa inherits her mother’s stand at Fyakubantu market.', 'Pa Maliketi is a Zambian comedy series for Zambezi Magic. Official DStv / Zambezi Magic promos introduce Bana Mwansa inheriting her mother’s market stand at Fyakubantu market and navigating the drama around her. Kinorium lists Owas Ray Mwape as director and names cast including Elizabeth Chisela, Philomena Nyirenda, Robert Nyirenda, Taonga Phiri and Innocent Tembo. MultiChoice Zambia announced Pa Maliketi Season 2 among its April 2025 local slate (premiere cited 24 April 2025). Season 1 promotional key art in the ORAM archive carries Zambezi Magic / DStv 162 / GOtv Supa branding.',
      'Deliver a weekly market comedy for Zambezi Magic that could hold a Friday night appointment and later return for a second season in MultiChoice’s local slate.', 'Direction credited to Owas Ray Mwape (Kinorium). Story world centres on Fyakubantu market life — inheritance, gossip and community pressure — under Zambezi Magic’s “Sharing Our Stories” brand.', 'Network television for Zambezi Magic. Season 2 return confirmed in MultiChoice Zambia’s 2025 showcase reporting.',
      'ORAM vault holds Season 1 cover art and additional Pa Maliketi key frames. Cleared BTS stills are not yet wired on the public gallery.', NULL, '[{"value":"2023","label":"Series start (listed)"},{"value":"S2 Apr 2025","label":"Season 2 (MultiChoice slate)"},{"value":"DStv 162","label":"Zambezi Magic"},{"value":"Friday","label":"Weekly slot (promo)"}]', '[]',
      'Director credit (Kinorium). Classified as Directed by Owas Ray Mwape.', NULL, NULL, 'Zambezi Magic (production company per Kinorium listing)', NULL,
      'Zambezi Magic / MultiChoice', 'Zambezi Magic (DStv 162)', NULL,
      1, 5, 0, 1,
      'Pa Maliketi', 'Zambezi Magic market comedy — when Mwansa inherits her mother’s stand at Fyakubantu market.', NULL, NULL, 0,
      'overview', NULL, NULL, NULL, NULL, '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z'
    );
