    ) VALUES (
      'prod_the-wife', 'The Wife', 'the-wife', '[]',
      2013, NULL, 'Feature', 'feature',
      'released', 'published', 'personal-filmography', 'Early Owas Films feature — “For better, for worse…” Directed and executive-produced by Owas Ray Mwape.', 'The Wife is a Zambian feature presented by Old Age Productions, Owas Films and Maynarj Films. The official poster tagline reads “For better, for worse…”. Owas Ray Mwape is credited as director and executive producer, and appears in the cast. Production is billed as Owas Films and Old Age Productions in conjunction with Maynarj Films. Cast named on the poster includes Meyer Nyirenda, Owas Ray Mwape, Webster Chiluba, Adora Mwape, Charles Simusokwe, and introducing Mwelwa Muswema. Director of Cinematography: Maynard Muchangwe. Industry biographies place the film around the 2013 founding of Owas Films; the poster itself does not print a release year.',
      'Launch an independent Zambian feature under the new Owas Films banner — domestic drama with theatrical key art and a full billing block.', 'Owas Ray Mwape directed and executive-produced while also appearing on screen. Key art places a hard-hat central figure against a city skyline with three women — a domestic triangle under urban pressure.', 'Independent feature: Owas Films / Old Age Productions in conjunction with Maynarj Films. No official trailer is wired on this site. A YouTube upload titled “Wife from above” exists in public search results but is a different title and must not be confused with The Wife without verification.',
      'Official poster is the primary cleared still in the ORAM vault. Unit photography not yet on the public gallery.', NULL, '[{"value":"~2013","label":"Cited era (verify premiere)"},{"value":"Owas Films","label":"Production banner"},{"value":"Feature","label":"Drama"}]', '["Poster tagline: “For better, for worse…”","Design credit on poster: Pule Mulenga.","Executive Associate Producers listed: Elizabeth Njobvu, Mutinta Chisiya, Ibrahim Mabvuto Kaumba."]',
      'Owas Films / Old Age Productions / Maynarj Films on poster — no ORAM Media Dynamics branding. Personal filmography. Do not claim as ORAM production.', NULL, NULL, 'Owas Films · Old Age Productions · Maynarj Films', NULL,
      'Owas Films / Old Age Productions', NULL, NULL,
      1, 9, 1, 1,
      'The Wife', 'Early Owas Films feature — “For better, for worse…” Directed and executive-produced by Owas Ray Mwape.', NULL, NULL, 0,
      'overview', NULL, NULL, NULL, NULL, '2026-07-18T00:00:00.000Z', '2026-07-18T00:00:00.000Z'
    );
